/**
 *  One watched folder entry. The `id` is generated client-side (uuid)
 *  so settings writes from the UI never collide with concurrent watcher
 *  events for the same folder.
 */
export type WatchFolderConfig = {
	id: string,
	path: string,
	output_format?: WatchFolderOutputFormat,
	/**
	 *  Runtime health exposed to the UI. This is recomputed when the app
	 *  lists watch folders so stale deleted folders do not look active.
	 */
	missing?: boolean,
	/**
	 *  When true, the source audio file is deleted after a successful
	 *  transcription. Defaults to false because losing recordings to a
	 *  silent typo would be very bad.
	 */
	delete_after?: boolean,
	/**
	 *  Soft on/off for the row in the UI. The watcher service skips
	 *  disabled rows entirely so users can pause without removing them.
	 */
	enabled?: boolean,
};

/**
 *  One audio/video file that already exists inside a watched folder,
 *  surfaced so the user can pick which pre-existing files to transcribe.
 */
export type WatchFolderExistingFile = {
	/**  Absolute path, fed back into `transcribe_watch_folder_files`. */
	path: string,
	/**  Path relative to the watched root, for display. */
	relative_path: string,
	size_bytes: number,
	/**
	 *  True when a transcript in the folder's current output format is
	 *  already sitting next to the source file.
	 */
	has_transcript: boolean,
	/**
	 *  Whether the sibling transcript is missing, present, or suspiciously
	 *  small and worth rerunning.
	 */
	transcript_status: WatchFolderTranscriptStatus,
	/**  User-facing reason when `transcript_status` is `needs_review`. */
	transcript_warning: string | null,
};

/**  Output format for files written by the watch-folder service. */
export type WatchFolderOutputFormat =
/**  Plain transcript next to the source file as `<basename>.txt`. */
"text" |
/**
 *  SubRip subtitles (`.srt`); only meaningful when the engine
 *  produced timed segments (Whisper / Parakeet today).
 */
"srt" |
/**  WebVTT subtitles (`.vtt`); same caveat as SRT. */
"vtt";

/**  Existing transcript state for a source file in a watched folder. */
export type WatchFolderTranscriptStatus = "missing" | "present" | "needs_review";

export type WindowsMicrophonePermissionStatus = {
	supported: boolean,
	overall_access: PermissionAccess,
	device_access: PermissionAccess,
	app_access: PermissionAccess,
	desktop_app_access: PermissionAccess,
};

